import { createProject, NotFoundError, ProjectRepository } from "../domain";
import { ProjectDto, toProjectDto } from "./dto";
import { Clock, IdGenerator } from "./ports";

export class ProjectService {
  constructor(
    private readonly projects: ProjectRepository,
    private readonly ids: IdGenerator,
    private readonly clock: Clock,
  ) {}

  create(name: string): ProjectDto {
    const project = createProject(this.ids.next(), name, this.clock.now());
    this.projects.save(project);
    return toProjectDto(project);
  }

  get(id: string): ProjectDto {
    const project = this.projects.findById(id);
    if (!project) {
      throw new NotFoundError(`Project ${id} not found`);
    }
    return toProjectDto(project);
  }

  list(): ProjectDto[] {
    return this.projects.findAll().map(toProjectDto);
  }
}

