import {
  NotFoundError,
  ProjectRepository,
  Task,
  TaskFilter,
  TaskRepository,
  TaskStatus,
  UserRepository,
} from "../domain";
import { TaskDto, toTaskDto } from "./dto";
import { Clock, IdGenerator } from "./ports";

export interface CreateTaskCommand {
  projectId: string;
  title: string;
  description: string;
  dueDate?: Date;
  status?: TaskStatus;
}

export class TaskService {
  constructor(
    private readonly tasks: TaskRepository,
    private readonly projects: ProjectRepository,
    private readonly users: UserRepository,
    private readonly ids: IdGenerator,
    private readonly clock: Clock,
  ) {}

  create(command: CreateTaskCommand): TaskDto {
    this.requireProject(command.projectId);
    const task = new Task({
      id: this.ids.next(),
      projectId: command.projectId,
      title: command.title,
      description: command.description,
      dueDate: command.dueDate,
      status: command.status,
      createdAt: this.clock.now(),
    });
    this.tasks.save(task);
    return toTaskDto(task);
  }

  get(projectId: string, taskId: string): TaskDto {
    return toTaskDto(this.requireTask(projectId, taskId));
  }

  list(projectId: string, filter: TaskFilter): TaskDto[] {
    this.requireProject(projectId);
    return this.tasks.findByProject(projectId, filter).map(toTaskDto);
  }

  assign(projectId: string, taskId: string, userId: string): TaskDto {
    const task = this.requireTask(projectId, taskId);
    if (!this.users.findById(userId)) {
      throw new NotFoundError(`User ${userId} not found`);
    }
    task.assignTo(userId);
    this.tasks.save(task);
    return toTaskDto(task);
  }

  markDone(projectId: string, taskId: string): TaskDto {
    const task = this.requireTask(projectId, taskId);
    task.markDone(this.clock.now());
    this.tasks.save(task);
    return toTaskDto(task);
  }

  private requireProject(projectId: string): void {
    if (!this.projects.findById(projectId)) {
      throw new NotFoundError(`Project ${projectId} not found`);
    }
  }

  private requireTask(projectId: string, taskId: string): Task {
    this.requireProject(projectId);
    const task = this.tasks.findById(taskId);
    if (!task || task.projectId !== projectId) {
      throw new NotFoundError(`Task ${taskId} not found in project ${projectId}`);
    }
    return task;
  }
}

