import { createUser, NotFoundError, UserRepository } from "../domain";
import { toUserDto, UserDto } from "./dto";
import { IdGenerator } from "./ports";

export class UserService {
  constructor(
    private readonly users: UserRepository,
    private readonly ids: IdGenerator,
  ) {}

  register(name: string): UserDto {
    const user = createUser(this.ids.next(), name);
    this.users.save(user);
    return toUserDto(user);
  }

  get(id: string): UserDto {
    const user = this.users.findById(id);
    if (!user) {
      throw new NotFoundError(`User ${id} not found`);
    }
    return toUserDto(user);
  }

  list(): UserDto[] {
    return this.users.findAll().map(toUserDto);
  }
}

